// Checks for the Fee & Scholarship Calculator logic (src/utils/feeCalculator.ts).
//   npm run test:calc
// 1. What a student types is understood correctly ("EAPCET 9000", "850", "88%", "850/1000" ...).
// 2. Every amount the calculator works out equals the backend's answer for the same input
//    (scripts/feeCases.json is generated by backend/scripts/export_fee_config.py). The calculator does no fee
//    maths: it reads the engine's own numbers, so this checks it reads the right row.
// 3. The CSE 95% example from the 2027-28 fee circular: Sem 1 ₹1,44,000, Sem 2 ₹1,19,000, Year 1 ₹2,63,000.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  calculateParams, estimateFromBackend, estimateFromConfig, inr, matchSlab, parseScore, rupees, scholarshipStartText,
} from "../src/utils/feeCalculator.ts";

const load = (path) => JSON.parse(readFileSync(new URL(path, import.meta.url), "utf8"));
const config = load("../src/data/feeConfig.json");
const cases = load("./feeCases.json");
const prog = (id) => config.programs.find((p) => p.id === id);
const cse = prog("btech_cse");
const mba = prog("mba");
let checks = 0;
const eq = (actual, expected, label) => { assert.deepEqual(actual, expected, label); checks++; };

// ---- 1. understanding the typed score ---------------------------------------------------
const parse = (text, exam = "state_board", program = cse) => parseScore(program, exam, text);
const pctFor = (text, exam = "state_board", program = cse) => {
  const p = parse(text, exam, program);
  return p.status === "ok" ? matchSlab(program, p.examKey, p.value) : p.status;
};

// The 16 Nov blocker: an EAPCET rank typed while "State Board" is selected.
let p = parse("EAPCET 9000");
eq([p.status, p.examKey, p.value, p.switched, p.display], ["ok", "eapcet_rank", 9000, true, "EAPCET rank 9,000"], "EAPCET 9000");
eq(pctFor("EAPCET 9000"), 25, "rank 9000 -> 25%");
eq(pctFor("eamcet rank 4,500"), 30, "rank 4,500 -> 30%");
eq(pctFor("rank 1500"), 40, "rank 1500 -> 40%");
eq(pctFor("9000"), 25, "a bare number above 1000 is a rank");
eq(pctFor("45000"), 0, "rank beyond the slabs -> standard fee");
eq(parse("45000").examKey, "eapcet_rank", "45000 is read as a rank");

eq(pctFor("85"), 25, "85 -> 25%");
eq(pctFor("85%"), 25, "85%");
eq(pctFor("850"), 25, "850 marks out of 1000");
eq(parse("850").display, "850/1000 (85%)", "marks display");
eq(pctFor("850/1000"), 25, "fraction");
eq(pctFor("920 out of 1000"), 30, "out of");
eq(pctFor("59.9"), 0, "below 60%");
eq(pctFor("98"), 40, "98%");
eq(pctFor("460", "cbse"), 30, "CBSE 460/500 = 92%");
eq(pctFor("cbse 93"), 30, "typed CBSE switches the board");
eq(pctFor("jee 92.4"), 30, "JEE percentile");
eq(pctFor("IB 36"), 30, "IB score");
eq(pctFor("88%", "eapcet_rank"), 25, "a % sign is never a rank, even with EAPCET selected");
eq(pctFor("85", "eapcet_rank"), 40, "a bare number with EAPCET selected is a rank");
eq(pctFor("75", "state_board", mba), 20, "MBA: qualifying degree %");

for (const [text, exam, program] of [["", "state_board", cse], ["abc", "state_board", cse], ["120%", "state_board", cse],
  ["1200/1000", "state_board", cse], ["eapcet 9000", "state_board", mba], ["jee 130", "state_board", cse],
  ["ib 50", "state_board", cse], ["rank 0", "state_board", cse]]) {
  const r = parseScore(program, exam, text);
  assert.notEqual(r.status, "ok", `"${text}" must not be accepted`);
  checks++;
}
eq(parse("").status, "empty", "empty");
assert.match(parseScore(mba, "state_board", "eapcet 9000").message, /not used for MBA/);
eq(scholarshipStartText(cse, "state_board"), "Merit scholarship starts at 60%", "start text");
eq(scholarshipStartText(cse, "eapcet_rank"), "Rank scholarships cover EAPCET ranks up to 20,000", "rank start text");
eq(calculateParams("btech_cse", parse("EAPCET 9000"), "none"),
  { program: "btech_cse", board: "state_board", percent: undefined, eapcet_rank: 9000, jee_percentile: undefined, ib_score: undefined, hostel: "none", transport: false },
  "request sent to the backend");
eq([inr(255000), rupees("₹2,55,000")], ["₹2,55,000", 255000], "rupee formatting");

// ---- 2. the calculator's arithmetic equals the backend's, case by case --------------------
for (const c of cases) {
  const program = prog(c.program);
  const label = `${c.program} ${JSON.stringify({ percent: c.percent, board: c.board, rank: c.eapcet_rank, jee: c.jee_percentile, ib: c.ib_score })} hostel=${c.hostel}`;
  // the same route the screen takes: typed text -> parsed score -> slab -> estimate
  let text = "", exam = "state_board";
  if (c.eapcet_rank !== undefined) text = `EAPCET ${c.eapcet_rank}`;
  else if (c.jee_percentile !== undefined) text = `jee ${c.jee_percentile}`;
  else if (c.ib_score !== undefined) text = `IB ${c.ib_score}`;
  else if (c.percent !== undefined) { text = `${c.percent}%`; exam = c.board === "cbse" ? "cbse" : "state_board"; }
  const parsed = parseScore(program, exam, text);
  const offered = program.exams.some((e) => e.key === parsed.examKey);
  const pct = parsed.status === "ok" && offered ? matchSlab(program, parsed.examKey, parsed.value) : 0;
  if (parsed.status === "invalid") {
    // e.g. an EAPCET rank on a PG course: the backend ignores it too (standard fee)
    eq(c.expect.scholarship_percent, 0, `${label}: backend also gives no scholarship`);
    continue;
  }
  const est = estimateFromConfig(config, program, pct, parsed.examKey);
  eq(est.scholarshipPercent, c.expect.scholarship_percent, `${label}: scholarship %`);
  eq(inr(est.tuitionYear), c.expect.tuition_first_year, `${label}: tuition`);
  eq(inr(est.netYear), c.expect.tuition_first_year_after_scholarship, `${label}: net tuition`);
  eq(inr(est.netSem), c.expect.per_semester_after_scholarship, `${label}: per semester`);
  eq(inr(est.savingYear), c.expect.saving_first_year, `${label}: saving`);
  eq(inr(est.semesters[0].total), c.expect.sem1_total_payable, `${label}: semester 1 total`);
  eq(inr(est.semesters[1].total), c.expect.sem2_total_payable, `${label}: semester 2 total`);
  eq(inr(est.firstYearTotal), c.expect.first_year_total_payable, `${label}: first year total`);
  eq(inr(est.applicationFee), c.expect.application_fee, `${label}: application fee shown separately`);
  eq(est.years.map(inr), c.years, `${label}: year by year`);
  if (c.expect.full_course_total) eq(inr(est.fullCourseTotal), c.expect.full_course_total, `${label}: full course`);
  // and a backend reply maps back to the same numbers
  const mapped = estimateFromBackend({
    scholarship_percent: c.expect.scholarship_percent, tuition_first_year: c.expect.tuition_first_year,
    tuition_first_year_after_scholarship: c.expect.tuition_first_year_after_scholarship,
    per_semester_after_scholarship: c.expect.per_semester_after_scholarship, saving_first_year: c.expect.saving_first_year,
    semester_1: { total: c.expect.sem1_total_payable, items: [] }, semester_2: { total: c.expect.sem2_total_payable, items: [] },
    first_year_total_payable: c.expect.first_year_total_payable, full_course_total: c.expect.full_course_total,
    application_fee: c.expect.application_fee,
  });
  eq([mapped.netYear, mapped.firstYearTotal, mapped.semesters[0].total, mapped.semesters[1].total],
     [est.netYear, est.firstYearTotal, est.semesters[0].total, est.semesters[1].total], `${label}: backend mapping`);
}

// ---- 3. the circular's worked example --------------------------------------------------------
{
  const p95 = parseScore(cse, "state_board", "95%");
  const est = estimateFromConfig(config, cse, matchSlab(cse, p95.examKey, p95.value), p95.examKey);
  eq(est.scholarshipPercent, 30, "95% Inter -> 30%");
  const s1 = Object.fromEntries(est.semesters[0].items.map((i) => [i.label, i.amount]));
  eq(s1, { "Tuition": 119000, "Enrollment fee": 5000, "Other fee": 15000, "Exam fee (Year 1)": 5000 }, "Semester 1 items");
  eq(est.semesters[1].items.map((i) => [i.label, i.amount]), [["Tuition", 119000]], "Semester 2 is tuition only");
  eq([est.semesters[0].total, est.semesters[1].total, est.firstYearTotal], [144000, 119000, 263000], "₹1,44,000 / ₹1,19,000 / ₹2,63,000");
  assert.notEqual(est.semesters[0].total, 131500, "never ₹1,31,500 in both semesters");
}

console.log(`Fee calculator: ${checks} checks passed (${cases.length} backend answers compared).`);
